import{_ as t,c as l,o as s,j as a,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易辨畫卷四十","description":"周易辨畫 - 周易辨畫卷四十","frontmatter":{"title":"周易辨畫卷四十","description":"周易辨畫 - 周易辨畫卷四十"},"headers":[],"relativePath":"classics/bianhua/041.md","filePath":"classics/bianhua/041.md"}'),r={name:"classics/bianhua/041.md"};function i(c,e,o,p,d,u){return s(),l("div",null,[...e[0]||(e[0]=[a("h1",{id:"周易辨畫卷四十",tabindex:"-1"},[n("周易辨畫卷四十 "),a("a",{class:"header-anchor",href:"#周易辨畫卷四十","aria-label":"Permalink to “周易辨畫卷四十”"},"​")],-1),a("p",null,"欽定四庫全書",-1),a("p",null,"潁川連斗山撰",-1),a("p",null,"大衍之數五十，加五則為河圖，減五則為洛書。此河洛二圖，聖人所為則之而作易也。朱子易學啟蒙曰：圖之左方，陽內陰外，即先天之震、離、兌、乾，陽長而陰消也。其右方陰內陽外，即先天之巽、坎、艮、坤，陰長而陽消也。蓋所以象二氣之交運也。朱子易學啟蒙曰：陽道主變，其數以進為極；陰道主化，其數以退為極。陽以進為極，故乾為父而得九，震長男而得八，坎中男而得七，艮少男而得六。凡成數皆陽主之。陰以退為極，故坤為母而得一，巽長女而得二，離中女而得三，兌少女而得四。凡生數皆陰主之，所以五數、十數不同。右伏羲八卦次序之圖。繫辭傳曰：「易有太極，是生兩儀，兩儀生四象，四象生八卦。」邵子曰：「一分為二，二分為四，四分為八也。」朱子易學啟蒙曰：圖之一六為水，居北，即後天之坎位也；三八為木，居東，即後天震、巽之位也；三七為火，居南，即後天之離位也；四九為金，居西，即後天兌、乾之位也。五十為土，居中。即後天之坤、艮，周流四季，而偏旺於醜、未之交也。蓋所以象五行之順布也。朱子易學啟蒙曰：「火上水下，故九數為離，一數為坎。火生燥土，故八次九為艮。燥土生金，故七、六次八而為兌，為乾。水生溼土，故二次一而為坤。溼土生木，故三、四次二而為震，為巽。以八數與八卦相配，而後天之位合矣。」右見說卦。邵子曰：「此文王八卦，乃入用之位，後天之學也。」又曰：「乾統三男於東北，坤統三女於西南。」按，四陽卦與四陰卦畫各相配，陽數奇，三男皆五數，合父三數，共十八數。陰數偶，三女皆四數，合母六數，亦共十八數。䷀乾變六 一變 ䷫姤䷌ 同人 ䷉履䷈ 小畜 ䷍ 大有 ䷪夬 變五二變 ䷠遁䷅訟䷸巽䷱鼎䷛ 大過 ䷘ 無妄 ䷤ 家人 ䷝離䷰革䷼ 中孚 ䷥睽䷹",-1),a("p",null,"兌䷙ 大畜 ䷄需䷡ 大變壯四、三變 ䷋否䷴漸䷷旅䷞鹹䷺渙䷿ 未濟 ䷮困䷑蠱䷯井䷟恆䷩益䷔ 噬嗑 ䷐隨䷕賁䷾ 既濟 ䷶",-1),a("p",null,"豐䷨損䷻節䷵ 歸妹 ䷊ 泰變 三、 四變 ䷓觀䷢晉䷬萃䷳艮䷦蹇䷽ 小過 ䷃蒙䷜坎䷧解䷭",-1),a("p",null,"升䷚頤䷂屯䷲震䷣ 明夷 ䷒臨 變二、",-1),a("p",null,"五變 ䷖剝䷇比䷏豫䷎謙䷆師䷗復 變一、 六變䷁坤此圖即前圖而橫布之，乾、坤列上下之位，離、坎居乾、坤之間，蓋離之中畫即坤，坎之中畫即乾也。乾、坤二畫消長於諸卦之中，而一歲之氣運一週焉。後天序卦反對原圖乾䷀乾坤䷁坤屯䷂蒙需䷄訟師䷆比 小畜 ䷉履泰䷊否 同人 ䷌ 有大 謙䷎豫隨䷐蠱臨䷒觀 噬嗑 ䷔賁剝䷖復 無妄 ䷘ 畜大 頤䷚頣 大過 ䷛ 過大 坎䷜坎離䷝離鹹䷞恆遁䷠ 壯大 晉䷢ 夷家明人 ䷤暌蹇䷞解損䷨益夬䷪姤萃䷬升困䷮井革䷰鼎震䷲艮漸䷴ 妹歸 豐䷶旅巽䷸兌渙䷺節 中孚 ䷼ 孚小中過 ䷽ 過既小濟 ䷾ 濟末 乾、坤、坎、離不易之卦，故上經以乾、坤居首，坎、離居終。乾交坤而為否，坤交乾而為泰，故上經十二卦而成居泰。兌、巽、震、艮反易之卦，故下經以兌艮、震巽相交居首，坎、離相交居終。艮交兌而為損，巽交震而為益，故下經十二卦而成損益。否、泰以天道言，損益以人事言也。右十二卦合十二支，而年月日時皆該周易辦畫。卷四十",-1)])])}const f=t(r,[["render",i]]);export{_ as __pageData,f as default};
